  const persist = (next: Database, action?: Parameters<typeof logActivity>[1], entity = 'system', id = 'system', description = '') => { if (action) logActivity(next, action, entity, id, description); setDatabase({ ...next }); saveDatabase(next); void pushCloudDatabase(next).catch(() => notify('تم الحفظ محليًا؛ تعذرت المزامنة السحابية')); };
  const syncNow = async () => { if (syncBusy) return; setSyncBusy(true); try { if (!cloudSyncConfigured()) throw new Error('المزامنة السحابية غير مهيأة'); const user = await getCloudUser(); if (!user) throw new Error('سجّل الدخول السحابي أولًا من نفس الصفحة'); saveDatabase(database); try { await pushCloudDatabase(database); notify('تم حفظ البيانات محليًا ومزامنتها سحابيًا بنجاح'); } catch (error) { if (!(error instanceof Error) || !error.message.startsWith('حدث تعارض')) throw error; const cloud = await pullCloudDatabase(); if (!cloud) throw error; const merged = mergeCloudDatabases(database, cloud); setDatabase(merged); saveDatabase(merged); await pushCloudDatabase(merged); notify('تم دمج آخر التعديلات من الأجهزة الأخرى ومزامنتها بنجاح'); } } catch (error) { notify(error instanceof Error ? error.message : 'تعذرت مزامنة البيانات'); } finally { setSyncBusy(false); } };
  useEffect(() => { let active = true; void hydrateDatabase().then(async (stored) => { if (!active) return; const [cloud, publicProducts] = await Promise.all([pullCloudDatabase().catch(() => null), pullPublicProducts()]); if (cloud && (hasUserData(cloud) || !hasUserData(stored))) setDatabase(mergeCloudImages(cloud, stored)); else if (stored) { const next = publicProducts.length ? { ...stored, products: publicProducts } : stored; setDatabase(next); if (hasUserData(stored)) void pushCloudDatabase(stored).catch(() => undefined); } else saveDatabase(publicProducts.length ? { ...initial(), products: publicProducts } : initial()); }).finally(() => { if (active) setStorageReady(true); }); const refreshAfterCloudLogin = () => { void (async () => { const local = await hydrateDatabase().catch(() => null); const cloud = await pullCloudDatabase().catch(() => null); if (cloud && (hasUserData(cloud) || !hasUserData(local))) { const merged = mergeCloudImages(cloud, local); setDatabase(merged); saveDatabase(merged); } else if (local) { setDatabase(local); void pushCloudDatabase(local).catch(() => notify('تم تسجيل الدخول، لكن تعذرت مزامنة البيانات')); } })(); }; window.addEventListener('aqsaty-cloud-auth', refreshAfterCloudLogin); return () => { active = false; window.removeEventListener('aqsaty-cloud-auth', refreshAfterCloudLogin); }; }, []);
  useEffect(() => { const timer = window.setTimeout(() => setIntroVisible(false), 1450); return () => window.clearTimeout(timer); }, []);
  useEffect(() => { const number = new URLSearchParams(window.location.search).get('verify'); if (number) void verifyPublicContract(number).then(setVerification); }, []);
  const lookup = customerByPhone(database, lookupPhone); const total = database.contracts.reduce((sum, c) => sum + c.financedAmount, 0); const paid = database.contracts.reduce((sum, c) => sum + paidFor(database, c), 0);
  const due = database.contracts.flatMap((contract) => contract.schedule.filter((item) => item.paidAmount < item.amount && isOverdue(item.dueDate)).map((schedule) => ({ contract, schedule })));
  const openAdmin = () => sessionStorage.getItem('aqsaty_admin') === '1' ? setAdmin(true) : setLoginOpen(true);
