  const sendReceiptWhatsApp = (contractId: string, scheduleId: string) => { const payment = [...database.payments].reverse().find((item) => item.contractId === contractId && item.scheduleId === scheduleId); const contract = database.contracts.find((item) => item.id === contractId); const customer = contract && database.customers.find((item) => item.id === contract.customerId); if (!payment || !contract || !customer) return notify('تعذر تجهيز الإيصال'); const message = `السلام عليكم ${customer.name}،\n\nتم استلام دفعة بقيمة ${money(payment.amount)} لدى ${database.settings.shopName}.\nرقم الإيصال: ${payment.receiptNumber}\nالمنتج: ${contract.productName}\nالعقد: ${contract.number}\nالتاريخ: ${dateText(payment.date)}\nالمتبقي على العقد: ${money(contractStats(database, contract).remaining)}\n\nشكرًا لتعاونكم.`; window.open(`https://wa.me/${normalizePhone(customer.phone).replace(/^0/, '964')}?text=${encodeURIComponent(message)}`, '_blank', 'noopener'); };
