  const saveContract = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const customerId = context.customerId!; const productId = String(data.get('productId') || ''); const product = database.products.find((p) => p.id === productId); const productName = product?.name || String(data.get('productName') || '').trim(); const totalAmount = Number(data.get('total')); const downPayment = Number(data.get('down') || 0); const months = Number(data.get('months')); const startDate = String(data.get('startDate')); if (!productName || !Number.isFinite(totalAmount) || totalAmount <= 0 || !Number.isFinite(downPayment) || downPayment < 0 || downPayment >= totalAmount || !Number.isInteger(months) || months <= 0 || !startDate) return notify('أكمل بيانات العقد بشكل صحيح'); const serialNumber = String(data.get('serial') || '').trim(); if (product && serialNumber && !product.serialNumbers.includes(serialNumber)) return notify('الرقم التسلسلي غير موجود ضمن مخزون المنتج'); const contract: Contract = { id: createId('contract'), number: `AQ-${new Date().getFullYear()}-${String(database.contracts.length + 1).padStart(5, '0')}`, customerId, productId, productName, serialNumber, totalAmount, downPayment, financedAmount: totalAmount - downPayment, months, startDate, status: 'نشط', schedule: createSchedule(totalAmount - downPayment, months, startDate), createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() }; const products = database.products.map((item) => item.id === productId ? { ...item, stock: Math.max(0, item.stock - 1), serialNumbers: item.serialNumbers.filter((serial) => serial !== serialNumber) } : item); persist({ ...database, contracts: [...database.contracts, contract], products }, 'إنشاء', 'contract', contract.id, `إنشاء العقد ${contract.number}`); setForm(null); notify('تم إنشاء العقد وجدول الأقساط'); };
  const saveEditedContract = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const current = database.contracts.find((item) => item.id === context.contractId); if (!current) return notify('العقد غير موجود'); try { const next = structuredClone(database); updateContract(next, current.id, { productName: String(data.get('productName') || '').trim(), totalAmount: Number(data.get('total')), downPayment: Number(data.get('down') || 0), months: Number(data.get('months')), startDate: String(data.get('startDate')), status: String(data.get('status')) as ContractStatus }); persist(next); setForm(null); notify('تم تعديل العقد وجدول الأقساط'); } catch (error) { notify(error instanceof Error ? error.message : 'تعذر تعديل العقد'); } };
  const saveProduct = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const name = String(data.get('name') || '').trim(); const price = Number(data.get('price')); const months = data.getAll('months').map(Number); if (!name || !price || !months.length) return notify('أكمل بيانات المنتج'); const serialNumbers = String(data.get('serialNumbers') || '').split(/[,\n]/).map((s) => s.trim()).filter(Boolean); const existing = database.products.find((item) => item.id === context.productId); const imageFiles = Array.from(data.getAll('images')).filter((item): item is File => item instanceof File && item.size > 0).slice(0, 10); let newImages: string[]; try { newImages = await Promise.all(imageFiles.map(compressProductImage)); } catch (error) { return notify(error instanceof Error ? error.message : 'تعذر ضغط صورة المنتج'); } const images = [...(newImages.length ? newImages : (existing?.images || []))].slice(0, 10); const record: Product = { id: context.productId || createId('product'), name, category: String(data.get('category') || ''), description: String(data.get('description') || ''), price, months, icon: String(data.get('icon') || '📦') as ProductIcon, active: true, stock: Number(data.get('stock') || serialNumbers.length || 0), serialNumbers, condition: String(data.get('condition') || 'جديد') as Product['condition'], images, specs: String(data.get('specs') || ''), warranty: String(data.get('warranty') || '') }; const products = context.productId ? database.products.map((item) => item.id === record.id ? record : item) : [...database.products, record]; persist({ ...database, products }, 'تعديل', 'product', record.id, `حفظ المنتج ${record.name}`); setForm(null); notify('تم حفظ المنتج'); };
