  const saveReschedule = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); try { const next = structuredClone(database); rescheduleItem(next, context.contractId!, context.scheduleId!, String(data.get('date')), Number(data.get('amount') || 0)); persist(next); setForm(null); notify('تمت إعادة جدولة القسط'); } catch { notify('تعذر إعادة الجدولة'); } };
